#nullable enable

using System;
using System.Threading;
using System.Threading.Tasks;
using Campground.Shared.Registry;

namespace Campground.Shared.Contracts
{
    /// <summary>A port (range) a plugin needs reachable from outside.</summary>
    internal sealed record PortRequest(
        string PluginId,
        string Purpose,
        string Protocol,
        int FirstPort,
        int LastPort,
        bool NeedsRouterForward,
        bool NeedsHostFirewall);

    /// <summary>The state of a port request.</summary>
    internal sealed record PortStatus(string State, string Message, string? ManualInstructions);

    /// <summary>
    /// <c>campground.ports.v1</c> — plugins ask Trailhead for router forwards and firewall rules
    /// (e.g. GameTent's WebRTC UDP range). Trailhead owns router and firewall changes; without it the plugin
    /// shows <see cref="ManualInstructions"/>.
    /// </summary>
    internal static class PortsClient
    {
        internal const string RequestOp = "request";
        internal const string ReleaseOp = "release";
        internal const string StatusOp = "status";

        /// <summary>States.</summary>
        internal static class States
        {
            internal const string Open = "open";
            internal const string Pending = "pending";
            internal const string Failed = "failed";
            internal const string Manual = "manual";
        }

        /// <summary>Requests a forward; falls back to manual instructions when Trailhead is missing.</summary>
        internal static async Task<PortStatus> RequestAsync(PortRequest request, CancellationToken ct = default)
        {
            var status = await Capabilities.TryInvokeAsync<PortStatus>(
                CapabilityNames.Ports, RequestOp, request, timeout: TimeSpan.FromSeconds(10), ct: ct).ConfigureAwait(false);
            return status ?? new PortStatus(States.Manual, "Trailhead isn't installed, so this has to be set up by hand.", ManualInstructions(request));
        }

        /// <summary>Releases a forward (best effort).</summary>
        internal static Task ReleaseAsync(PortRequest request, CancellationToken ct = default)
            => Capabilities.TryInvokeAsync(CapabilityNames.Ports, ReleaseOp, request, ct: ct);

        /// <summary>Plain-language manual steps.</summary>
        internal static string ManualInstructions(PortRequest r)
        {
            var range = r.FirstPort == r.LastPort ? r.FirstPort.ToString(System.Globalization.CultureInfo.InvariantCulture) : $"{r.FirstPort}–{r.LastPort}";
            var steps = $"{r.Purpose} needs {r.Protocol.ToUpperInvariant()} port {range} reachable.";
            if (r.NeedsRouterForward)
            {
                steps += $" On your router, forward {r.Protocol.ToUpperInvariant()} {range} to this server's local address.";
            }

            if (r.NeedsHostFirewall)
            {
                steps += $" On this server, allow inbound {r.Protocol.ToUpperInvariant()} {range} in the firewall.";
            }

            return steps;
        }

        /// <summary>For the provider (Trailhead).</summary>
        internal static void Provide(
            string pluginId,
            int minor,
            Func<PortRequest, CancellationToken, Task<PortStatus>> request,
            Func<PortRequest, CancellationToken, Task<PortStatus>> release,
            Func<PortRequest, CancellationToken, Task<PortStatus>> status)
            => Capabilities.Provide(
                CapabilityNames.Ports,
                pluginId,
                minor,
                new CapabilityHost().On(RequestOp, request).On(ReleaseOp, release).On(StatusOp, status).Build());
    }
}
